{
  "root": "main_stack",
  "state": {
    "itineraryRows": [
      {
        "dayDate": "Day 1: Thursday, September 5, 2024",
        "icon": "../assets/r_000306_01_1_airplane.svg",
        "morningActivity": "12:00 PM: Arrive at Seattle-Tacoma International Airport (SEA). Transfer to hotel.",
        "afternoonActivity": "03:00 PM: Hotel check-in at The Edgewater Hotel (Pier 67). Settle in and prepare for meetings.",
        "dinnerSuggestion": "Casual dinner at a local restaurant near the hotel, such as Ivar's Acres of Clams."
      },
      {
        "dayDate": "Day 2: Friday, September 6, 2024",
        "icon": "../assets/r_000321_01_6_building.svg",
        "morningActivity": "10:00 AM - 11:30 AM: First business meeting at Client Office (e.g., Downtown Seattle).",
        "lunchActivity": "12:00 PM - 01:30 PM: Business lunch near meeting location.",
        "afternoonActivity": "02:00 PM - 03:30 PM: Second business meeting at Team Office (e.g., South Lake Union).",
        "dinnerSuggestion": "Dinner at a recommended restaurant, perhaps in the Belltown area."
      },
      {
        "dayDate": "Day 3: Saturday, September 7, 2024",
        "icon": "../assets/r_000306_01_1_airplane.svg",
        "morningActivity": "11:00 AM: Hotel check-out from The Edgewater Hotel.",
        "afternoonActivity": "12:00 PM: Travel to Seattle-Tacoma International Airport (SEA). 03:00 PM: Depart from Seattle-Tacoma International Airport (SEA).",
        "dinnerSuggestion": "Grab a meal at the airport before your flight."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "intro_text",
        "daily_itinerary_heading_stack",
        "itinerary_table",
        "quick_actions_heading",
        "quick_actions_stack",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Seattle Business Trip: September 5-7, 2024",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This itinerary outlines a business trip to Seattle, USA, from Thursday, September 5, to Saturday, September 7, 2024. It includes assumed flight times, hotel arrangements, and two scheduled meetings on September 6. All times are in Pacific Standard Time (PST).",
        "variant": "body"
      },
      "children": []
    },
    "daily_itinerary_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "daily_itinerary_icon",
        "daily_itinerary_text"
      ]
    },
    "daily_itinerary_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000323_01_1_calendar.svg"
      },
      "children": []
    },
    "daily_itinerary_text": {
      "type": "Text",
      "props": {
        "text": "Daily Itinerary",
        "variant": "h3"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itineraryRows",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayDate",
        "highlightColumns": [
          "morningActivity",
          "afternoonActivity"
        ],
        "columns": [
          {
            "key": "dayDate",
            "label": "Day & Date"
          },
          {
            "key": "icon",
            "label": "Type"
          },
          {
            "key": "morningActivity",
            "label": "Morning"
          },
          {
            "key": "lunchActivity",
            "label": "Lunch"
          },
          {
            "key": "afternoonActivity",
            "label": "Afternoon"
          },
          {
            "key": "dinnerSuggestion",
            "label": "Dinner"
          }
        ]
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "book_flights_button",
        "book_hotel_button"
      ]
    },
    "book_flights_button": {
      "type": "Button",
      "props": {
        "label": "Book Flights"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/flights"
          }
        }
      },
      "children": []
    },
    "book_hotel_button": {
      "type": "Button",
      "props": {
        "label": "Book Hotel"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.edgewaterhotel.com/"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sea_tac_button",
        "edgewater_hotel_button"
      ]
    },
    "sea_tac_button": {
      "type": "Button",
      "props": {
        "label": "Seattle-Tacoma International Airport"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.portseattle.org/sea-tac"
          }
        }
      },
      "children": []
    },
    "edgewater_hotel_button": {
      "type": "Button",
      "props": {
        "label": "The Edgewater Hotel"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.edgewaterhotel.com/"
          }
        }
      },
      "children": []
    }
  }
}
